function perfectpixel_daily_sold_today( $product_id ) {
	$key  = 'perfectpixel_daily_sold_' . $product_id . '_' . current_time( 'Ymd' );
	$sold = get_transient( $key );
	if ( false === $sold ) {
		$sold   = 0;
		$orders = wc_get_orders(
			array(
				'status'       => array( 'processing', 'on-hold', 'completed' ),
				'date_created' => '>=' . strtotime( current_time( 'Y-m-d' ) . ' 00:00:00 ' . wp_timezone_string() ),
				'limit'        => -1,
				'type'         => 'shop_order',
			)
		);
		foreach ( $orders as $order ) {
			foreach ( $order->get_items() as $item ) {
				if ( (int) $item->get_product_id() === (int) $product_id ) {
					$sold += (int) $item->get_quantity();
				}
			}
		}
		set_transient( $key, $sold, 5 * MINUTE_IN_SECONDS );
	}
	return (int) $sold;
}

function perfectpixel_daily_sales_limit( $purchasable, $product ) {
	$id = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
	if ( ! $purchasable || is_admin() || ! in_array( $id, wp_parse_id_list( '{{daily_limit_product_ids}}' ), true ) ) {
		return $purchasable;
	}
	return perfectpixel_daily_sold_today( $id ) < max( 1, (int) '{{daily_limit_qty}}' );
}

function perfectpixel_daily_sales_flush() {
	foreach ( wp_parse_id_list( '{{daily_limit_product_ids}}' ) as $id ) {
		delete_transient( 'perfectpixel_daily_sold_' . $id . '_' . current_time( 'Ymd' ) );
	}
}
